jest.mock(
  "rollup-plugin-dev",
  () => jest.fn((config: any) => ({ name: "dev", ...config })),
  { virtual: true },
);

jest.mock(
  "rollup-plugin-livereload",
  () => jest.fn((config: any) => ({ name: "livereload", ...config })),
  { virtual: true },
);

import type { Plugin, PluginContext } from "rollup";
import {
  servicenowFrontEndPlugins,
  createUpdateSrcPath,
} from "../../dist/index.js";

const makeCredential = (url = "https://dev12345.service-now.com/") => ({
  getUrl: () => new URL(url),
  getHeaders: async () => ({ Authorization: "Bearer token123" }),
});

describe("ServiceNow Front-End Plugins", () => {
  beforeEach(() => {
    jest.clearAllMocks();
    jest.spyOn(console, "warn").mockImplementation(() => {});
  });
  afterEach(() => {
    jest.restoreAllMocks();
  });

  describe("outputOptions configuration", () => {
    const findOutputOptionsPlugin = (plugins: Plugin | Plugin[]) => {
      const pluginArray = Array.isArray(plugins) ? plugins : [plugins];
      return pluginArray.find((p) => p && p.name === "output-options");
    };
    test("should configure entryFileNames and chunkFileNames without hash (to avoid creating delete records)", async () => {
      const plugins = await servicenowFrontEndPlugins({
        scope: "x_test_app",
        rootDir: "/project",
        registerExplicitId: () => "test-id",
      });

      const outputOptionsPlugin = findOutputOptionsPlugin(plugins as Plugin[]);
      expect(outputOptionsPlugin).toBeDefined();

      if (
        !outputOptionsPlugin ||
        typeof outputOptionsPlugin.outputOptions !== "function"
      ) {
        throw new Error("outputOptions plugin not found or invalid");
      }

      const rawOptions = {
        dir: "dist",
        format: "es" as const,
      };

      const result = await outputOptionsPlugin.outputOptions.call(
        {} as PluginContext,
        rawOptions,
      );

      expect(result).toEqual({
        dir: "dist",
        format: "es",
        entryFileNames: "[name].jsdbx",
        chunkFileNames: "[name].jsdbx",
      });
    });

    test("should configure chunkFileNames without content hash", async () => {
      const plugins = await servicenowFrontEndPlugins({
        scope: "x_test_app",
        rootDir: "/project",
        registerExplicitId: () => "test-id",
      });

      const outputOptionsPlugin = findOutputOptionsPlugin(plugins as Plugin[]);

      if (
        !outputOptionsPlugin ||
        typeof outputOptionsPlugin.outputOptions !== "function"
      ) {
        throw new Error("outputOptions plugin not found or invalid");
      }

      const rawOptions = {
        file: "dist/bundle.js",
      };

      const result = await outputOptionsPlugin.outputOptions.call(
        {} as PluginContext,
        rawOptions,
      );

      expect(result?.chunkFileNames).toBe("[name].jsdbx");
    });

    test("should handle array of output options", async () => {
      const plugins = await servicenowFrontEndPlugins({
        scope: "x_test_app",
        rootDir: "/project",
        registerExplicitId: () => "test-id",
      });

      const outputOptionsPlugin = findOutputOptionsPlugin(plugins as Plugin[]);

      if (
        !outputOptionsPlugin ||
        typeof outputOptionsPlugin.outputOptions !== "function"
      ) {
        throw new Error("outputOptions plugin not found or invalid");
      }

      const rawOptions: any = [
        { dir: "dist/esm", format: "es" as const },
        { dir: "dist/cjs", format: "cjs" as const },
      ];

      const result = await outputOptionsPlugin.outputOptions.call(
        {} as PluginContext,
        rawOptions,
      );

      expect(Array.isArray(result)).toBe(true);
      if (Array.isArray(result)) {
        expect(result[0].entryFileNames).toBe("[name].jsdbx");
        expect(result[0].chunkFileNames).toBe("[name].jsdbx");
        expect(result[1].entryFileNames).toBe("[name].jsdbx");
        expect(result[1].chunkFileNames).toBe("[name].jsdbx");
      }
    });

    test("should not modify output options when preserveSrc is true", async () => {
      const plugins = await servicenowFrontEndPlugins({
        scope: "x_test_app",
        rootDir: "/project",
        registerExplicitId: () => "test-id",
        dev: true, // Sets preserveSrc to true
      });

      const outputOptionsPlugin = findOutputOptionsPlugin(plugins as Plugin[]);
      expect(outputOptionsPlugin).toBeUndefined();
    });
  });

  describe("cache busting configuration", () => {
    /**
     * Helper to create updateSrcPath function with test configuration
     */
    const createUpdateSrcPathTest = (config: {
      enableCacheBusting?: boolean;
      preserveSrc?: boolean;
    }) => {
      return createUpdateSrcPath({
        scope: "x_test_app",
        preserveSrc: config.preserveSrc ?? false,
        enableCacheBusting: config.enableCacheBusting ?? true,
      });
    };

    test("should add cache busting parameter when enableCacheBusting is true", () => {
      const updateSrcPath = createUpdateSrcPathTest({
        enableCacheBusting: true,
      });

      const result = updateSrcPath("./script.js", "script");

      // Should include the cache busting parameter
      expect(result).toContain("/uxasset/externals/x_test_app/script.jsdbx?");
      expect(result).toContain(
        "uxpcb=$[UxFrameworkScriptables.getFlushTimestamp()]",
      );
    });

    test("should add cache busting parameter when enableCacheBusting is not specified (default is true)", () => {
      const updateSrcPath = createUpdateSrcPathTest({}); // Default is true

      const result = updateSrcPath("./script.js", "script");

      // Should include the cache busting parameter
      expect(result).toContain("/uxasset/externals/x_test_app/script.jsdbx?");
      expect(result).toContain(
        "uxpcb=$[UxFrameworkScriptables.getFlushTimestamp()]",
      );
    });

    test("should not add cache busting parameter when enableCacheBusting is false", () => {
      const updateSrcPath = createUpdateSrcPathTest({
        enableCacheBusting: false,
      });

      const result = updateSrcPath("./script.js", "script");

      // Should not include the cache busting parameter
      expect(result).toBe("/uxasset/externals/x_test_app/script.jsdbx");
      expect(result).not.toContain("uxpcb=");
    });

    test("should preserve query parameters from original path when enableCacheBusting is false", () => {
      const updateSrcPath = createUpdateSrcPathTest({
        enableCacheBusting: false,
      });

      const result = updateSrcPath(
        "./script.js?param1=value1&param2=value2",
        "script",
      );

      // Should preserve original query parameters but not add cache busting
      expect(result).toBe(
        "/uxasset/externals/x_test_app/script.jsdbx?param1=value1&param2=value2",
      );
      expect(result).not.toContain("uxpcb=");
    });

    test("should combine original query parameters with cache busting when enableCacheBusting is true", () => {
      const updateSrcPath = createUpdateSrcPathTest({
        enableCacheBusting: true,
      });

      const result = updateSrcPath("./script.js?param1=value1", "script");

      // Should include both original parameters and cache busting
      expect(result).toContain("/uxasset/externals/x_test_app/script.jsdbx?");
      expect(result).toContain("param1=value1");
      expect(result).toContain(
        "uxpcb=$[UxFrameworkScriptables.getFlushTimestamp()]",
      );
    });

    test("should respect preserveSrc when true", () => {
      const updateSrcPath = createUpdateSrcPathTest({ preserveSrc: true });

      const result = updateSrcPath("./script.js", "script-abc123.js");

      // Should return the emitted file name directly when preserveSrc is true
      expect(result).toBe("script-abc123.js");
      expect(result).not.toContain("/uxasset/externals/");
      expect(result).not.toContain("uxpcb=");
    });

    test("should strip .jsdbx extension from an already-extended emitted filename", () => {
      const updateSrcPath = createUpdateSrcPathTest({
        enableCacheBusting: false,
      });

      // rollup emits files with .jsdbx when outputOptions sets entryFileNames: "[name].jsdbx"
      const result = updateSrcPath("./script.js", "script.jsdbx");

      expect(result).toBe("/uxasset/externals/x_test_app/script.jsdbx");
    });

    test("should preserve subdirectory structure from emitted filename in the uxasset path", () => {
      const updateSrcPath = createUpdateSrcPathTest({
        enableCacheBusting: false,
      });

      const result = updateSrcPath(
        "./components/Button.tsx",
        "components/Button.jsdbx",
      );

      expect(result).toBe(
        "/uxasset/externals/x_test_app/components/Button.jsdbx",
      );
    });

    test("should override existing uxpcb parameter with Jelly tag when enableCacheBusting is true", () => {
      const updateSrcPath = createUpdateSrcPathTest({
        enableCacheBusting: true,
      });

      const result = updateSrcPath("./script.js?uxpcb=123456789", "script");

      // Should replace the existing uxpcb parameter with our Jelly tag
      expect(result).toContain("/uxasset/externals/x_test_app/script.jsdbx?");
      expect(result).not.toContain("uxpcb=123456789");
      expect(result).toContain(
        "uxpcb=$[UxFrameworkScriptables.getFlushTimestamp()]",
      );
    });
  });

  describe("integration with react type", () => {
    const expectedReactPluginNames = [
      "output-options",
      "html-script-entrypoints",
      "seismic",
      "replace",
      "url",
      "json",
      "css-url",
      "rollup-plugin-sass",
      "node-resolve",
      "swc",
      "swc-minify",
      "header",
      "sourcemap-url",
    ];

    test("should return expected plugin names by default", async () => {
      const plugins = await servicenowFrontEndPlugins({
        scope: "x_test_app",
        rootDir: "/project",
        registerExplicitId: () => "test-id",
      });

      const pluginNames = (plugins as any[])
        .flat()
        .map((p) => p?.name)
        .filter(Boolean);
      expect(pluginNames).toEqual(expectedReactPluginNames);
    });

    test("should return expected plugin names when type is react", async () => {
      const plugins = await servicenowFrontEndPlugins({
        type: "react",
        scope: "x_test_app",
        rootDir: "/project",
        registerExplicitId: () => "test-id",
      });

      const pluginNames = (plugins as any[])
        .flat()
        .map((p) => p?.name)
        .filter(Boolean);
      expect(pluginNames).toEqual(expectedReactPluginNames);
    });

    test("should return expected plugin names when dev is true", async () => {
      const plugins = await servicenowFrontEndPlugins({
        scope: "x_test_app",
        rootDir: "/project",
        registerExplicitId: () => "test-id",
        dev: true,
        watchPaths: ["dist/static"],
      });

      const pluginNames = (plugins as any[])
        .flat()
        .map((p) => p?.name)
        .filter(Boolean);
      expect(pluginNames).toEqual([
        "header",
        "html-script-entrypoints",
        "seismic",
        "replace",
        "url",
        "json",
        "css-url",
        "rollup-plugin-sass",
        "node-resolve",
        "swc",
        "swc-minify",
        "header",
        "dev",
        "livereload",
      ]);
    });

    test("should omit UXF globals header when omitDevUxGlobals is true in dev mode", async () => {
      const plugins = await servicenowFrontEndPlugins({
        scope: "x_test_app",
        rootDir: "/project",
        dev: true,
        watchPaths: ["dist/static"],
        omitDevUxGlobals: true,
      });

      const pluginNames = (plugins as any[])
        .flat()
        .map((p) => p?.name)
        .filter(Boolean);
      expect(pluginNames).toEqual([
        "html-script-entrypoints",
        "seismic",
        "replace",
        "url",
        "json",
        "css-url",
        "rollup-plugin-sass",
        "node-resolve",
        "swc",
        "swc-minify",
        "header",
        "dev",
        "livereload",
      ]);
    });

    test("should proxy the default ServiceNow paths when a credential is provided", async () => {
      const devServerMock = require("rollup-plugin-dev");
      await servicenowFrontEndPlugins({
        scope: "x_test_app",
        rootDir: "/project",
        dev: true,
        watchPaths: ["dist/static"],
        credential: makeCredential(),
      });
      const [{ proxy }] = devServerMock.mock.calls[0];
      const proxyFroms = proxy.map((p: any) => p.from);
      expect(proxyFroms).toEqual([
        "/api",
        "/amb",
        "/scripts/",
        "/images/@servicenow/",
        "/uxasset/externals",
        "/$uxappimmutables.do",
        "/uxta",
      ]);
    });
  });

  describe("registerExplicitId validation", () => {
    test("should throw when registerExplicitId is not provided and dev is false", async () => {
      await expect(
        servicenowFrontEndPlugins({
          scope: "x_test_app",
          rootDir: "/project",
        }),
      ).rejects.toThrow("registerExplicitId is required when dev is false");
    });

    test("should not throw when registerExplicitId is not provided and dev is true", async () => {
      await expect(
        servicenowFrontEndPlugins({
          scope: "x_test_app",
          rootDir: "/project",
          dev: true,
        }),
      ).resolves.not.toThrow();
    });
  });
});
